function collectBiomesInSelection(dimension, volume) {
    const {min, max} = volume.getBoundingBox();
    const found = [];
    const seen = new Set;
    for (let x = min.x; x <= max.x; x++) {
        for (let z = min.z; z <= max.z; z++) {
            for (let y = min.y; y <= max.y; y++) {
                const pos = {
                    x,
                    y,
                    z
                };
                if (!volume.isInside(pos)) {
                    continue;
                }
                const biome = dimension.getBiome(pos);
                if (!seen.has(biome.id)) {
                    seen.add(biome.id);
                    found.push(biome);
                }
            }
        }
    }
    return found;
}

